import { NextRequest, NextResponse } from "next/server";
import { newsTermsForPair } from "@/lib/constants";

const API_BASE_URL =
  process.env.MEDIASTACK_API_BASE_URL || "http://api.mediastack.com/v1";
const API_KEY = process.env.MEDIASTACK_API_KEY || "";

// Fetch fresh news at most once every 10 hours per keyword to stay within the
// Mediastack quota. We use a module-level cache (not Next's fetch cache) so we
// never persist a rate-limit/error response — and can serve the last good data
// if the API is briefly unavailable.
const TEN_HOURS_MS = 10 * 60 * 60 * 1000;
export const dynamic = "force-dynamic";

const cache = new Map<string, { at: number; articles: INewsArticle[] }>();

export interface INewsArticle {
  id: string;
  category: string;
  source: string;
  title: string;
  summary: string;
  publishedAt: string;
  time: string;
  image: string | null;
  url: string;
}

interface IMediastackArticle {
  title: string | null;
  description: string | null;
  url: string | null;
  source: string | null;
  image: string | null;
  category: string | null;
  published_at: string | null;
}

interface IMediastackResponse {
  data?: IMediastackArticle[];
  error?: { code?: string; message?: string };
}

function relativeTime(iso: string | null): string {
  if (!iso) return "";
  const then = new Date(iso).getTime();
  if (Number.isNaN(then)) return "";
  const mins = Math.round((Date.now() - then) / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

function titleCase(value: string): string {
  return value
    .split(/[\s_-]+/)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

function mapArticles(articles: IMediastackArticle[], term: string): INewsArticle[] {
  return articles
    .filter((a) => a.title && a.url)
    .map((a, i) => ({
      id: `${term}-${i}-${a.published_at ?? ""}`,
      category: a.category ? titleCase(a.category) : "Business",
      source: a.source ? titleCase(a.source) : "Newswire",
      title: a.title as string,
      summary: a.description?.trim() || "",
      publishedAt: a.published_at ?? "",
      time: relativeTime(a.published_at),
      image: a.image,
      url: a.url as string,
    }))
    .slice(0, 12);
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const from = (searchParams.get("from") || "USD").toUpperCase();
  const to = (searchParams.get("to") || "GHS").toUpperCase();
  const terms = newsTermsForPair(from, to);

  const cacheKey = terms[0];

  if (!API_KEY) {
    return NextResponse.json(
      { articles: [], error: "News API key not configured" },
      { status: 500 }
    );
  }

  // Serve from the 10h cache if it's still fresh.
  const cached = cache.get(cacheKey);
  if (cached && Date.now() - cached.at < TEN_HOURS_MS) {
    return NextResponse.json({ articles: cached.articles, keyword: cacheKey, cached: true });
  }

  // Try the specific term first, then broader ones, until we get articles.
  let lastError: string | null = null;
  for (const term of terms) {
    const params = new URLSearchParams({
      access_key: API_KEY,
      keywords: term,
      languages: "en",
      sort: "published_desc",
      limit: "20",
    });

    let json: IMediastackResponse;
    try {
      const res = await fetch(`${API_BASE_URL}/news?${params.toString()}`, {
        cache: "no-store",
      });
      json = (await res.json()) as IMediastackResponse;
    } catch {
      lastError = "Could not reach the news service";
      break;
    }

    if (json.error) {
      lastError = json.error.message || json.error.code || "News API error";
      break;
    }

    const articles = mapArticles(json.data ?? [], term);
    if (articles.length > 0) {
      cache.set(cacheKey, { at: Date.now(), articles });
      return NextResponse.json({ articles, keyword: term });
    }
  }

  // On error/empty: serve the last good data if we have any, else report.
  if (cached) {
    return NextResponse.json({ articles: cached.articles, keyword: cacheKey, stale: true });
  }
  return NextResponse.json(
    { articles: [], keyword: cacheKey, error: lastError ?? undefined },
    lastError ? { status: 502 } : undefined
  );
}

import { NextRequest, NextResponse } from "next/server";

const API_BASE_URL =
  process.env.EXCHANGERATES_API_BASE_URL || "http://api.exchangeratesapi.io/v1";
const API_KEY = process.env.EXCHANGERATES_API_KEY || "";

// The exchangeratesapi.io free plan doesn't allow the /convert endpoint or a
// non-EUR base, so we fetch the EUR-based rate table from /latest and compute
// every cross-rate locally. The table is cached in-memory so many conversions
// (every keystroke, popular pairs, etc.) cost at most one upstream call per
// refresh window — important given the tight free-tier rate limit.
const RATES_TTL_MS = 30 * 60 * 1000; // 30 minutes

interface IRateTable {
  at: number;
  timestamp: number;
  rates: Record<string, number>; // EUR-based
}

let cache: IRateTable | null = null;
let inflight: Promise<IRateTable | null> | null = null;

async function fetchEurRates(): Promise<IRateTable | null> {
  const params = new URLSearchParams({ access_key: API_KEY });
  const res = await fetch(`${API_BASE_URL}/latest?${params.toString()}`, {
    cache: "no-store",
  });
  const data = (await res.json()) as {
    success?: boolean;
    rates?: Record<string, number>;
    timestamp?: number;
    error?: { code?: string; message?: string };
  };
  if (!data.success || !data.rates) {
    return null;
  }
  return {
    at: Date.now(),
    timestamp: data.timestamp ?? Math.floor(Date.now() / 1000),
    rates: { ...data.rates, EUR: 1 },
  };
}

async function getRates(): Promise<IRateTable | null> {
  if (cache && Date.now() - cache.at < RATES_TTL_MS) return cache;
  // De-dupe concurrent refreshes.
  if (!inflight) {
    inflight = fetchEurRates()
      .then((fresh) => {
        if (fresh) cache = fresh;
        return cache;
      })
      .catch(() => cache)
      .finally(() => {
        inflight = null;
      });
  }
  return inflight;
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const from = searchParams.get("from")?.toUpperCase();
  const to = searchParams.get("to")?.toUpperCase();
  const amountStr = searchParams.get("amount");

  if (!from || !to || !amountStr) {
    return NextResponse.json(
      { error: "Missing required parameters: from, to, amount" },
      { status: 400 }
    );
  }

  const amount = Number(amountStr);
  if (Number.isNaN(amount)) {
    return NextResponse.json({ error: "Invalid amount" }, { status: 400 });
  }

  const table = await getRates();
  if (!table) {
    return NextResponse.json(
      { error: "Exchange rates are temporarily unavailable" },
      { status: 502 }
    );
  }

  const fromRate = from === "EUR" ? 1 : table.rates[from];
  const toRate = to === "EUR" ? 1 : table.rates[to];

  if (!fromRate || !toRate) {
    const missing = !fromRate ? from : to;
    return NextResponse.json(
      { error: `Unsupported currency: ${missing}` },
      { status: 400 }
    );
  }

  const rate = toRate / fromRate;
  const result = amount * rate;

  return NextResponse.json({
    success: true,
    query: { from, to, amount },
    info: { rate, timestamp: table.timestamp },
    result,
    date: new Date(table.timestamp * 1000).toISOString().slice(0, 10),
  });
}

import { NextRequest, NextResponse } from "next/server";

const API_BASE_URL =
  process.env.EXCHANGERATES_API_BASE_URL || "http://api.exchangeratesapi.io/v1";
const API_KEY = process.env.EXCHANGERATES_API_KEY || "";

export const dynamic = "force-dynamic";

// ~12 months of daily rates, grouped into this many OHLC candles.
const DAYS = 360;
const CANDLES = 30;
const TTL_MS = 6 * 60 * 60 * 1000; // 6h

export interface ICandle {
  open: number;
  high: number;
  low: number;
  close: number;
}

const cache = new Map<string, { at: number; candles: ICandle[] }>();

const fmt = (d: Date) => d.toISOString().slice(0, 10);

function buildCandles(series: { date: string; rate: number }[]): ICandle[] {
  series.sort((a, b) => a.date.localeCompare(b.date));
  if (series.length === 0) return [];
  const bucketSize = Math.max(1, Math.ceil(series.length / CANDLES));
  const candles: ICandle[] = [];
  for (let i = 0; i < series.length; i += bucketSize) {
    const chunk = series.slice(i, i + bucketSize);
    const rates = chunk.map((p) => p.rate);
    candles.push({
      open: chunk[0].rate,
      close: chunk[chunk.length - 1].rate,
      high: Math.max(...rates),
      low: Math.min(...rates),
    });
  }
  return candles;
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const base = (searchParams.get("base") || "USD").toUpperCase();
  const symbol = (searchParams.get("to") || "EUR").toUpperCase();

  if (base === symbol) {
    return NextResponse.json({ candles: [] });
  }
  if (!API_KEY) {
    return NextResponse.json({ candles: [], error: "No API key" }, { status: 500 });
  }

  const key = `${base}_${symbol}`;
  const cached = cache.get(key);
  if (cached && Date.now() - cached.at < TTL_MS) {
    return NextResponse.json({ candles: cached.candles, cached: true });
  }

  const end = new Date();
  const start = new Date();
  start.setDate(start.getDate() - DAYS);

  const params = new URLSearchParams({
    access_key: API_KEY,
    base,
    symbols: symbol,
    start_date: fmt(start),
    end_date: fmt(end),
  });

  try {
    const res = await fetch(`${API_BASE_URL}/timeseries?${params.toString()}`, {
      cache: "no-store",
    });
    const data = (await res.json()) as {
      success?: boolean;
      rates?: Record<string, Record<string, number>>;
      error?: { message?: string; info?: string };
    };

    if (!data.success || !data.rates) {
      return NextResponse.json(
        { candles: [], error: data.error?.info || data.error?.message || "Timeseries failed" },
        { status: 502 }
      );
    }

    const series = Object.entries(data.rates)
      .map(([date, r]) => ({ date, rate: r[symbol] }))
      .filter((p) => typeof p.rate === "number");

    const candles = buildCandles(series);
    if (candles.length > 0) {
      cache.set(key, { at: Date.now(), candles });
    }
    return NextResponse.json({ candles });
  } catch {
    // Serve stale if we have it, else signal failure.
    if (cached) return NextResponse.json({ candles: cached.candles, stale: true });
    return NextResponse.json({ candles: [], error: "unreachable" }, { status: 502 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { countryToCurrency } from "@/lib/constants";

const IPSTACK_BASE = process.env.IPSTACK_BASE_URL || "http://api.ipstack.com";
const API_KEY = process.env.IPSTACK_ACCESS_KEY || "";

export const dynamic = "force-dynamic";

// Cache the lookup per target IP so repeated page loads don't burn the tight
// ipstack rate limit. Successful results are reused for 6h.
const TTL_MS = 6 * 60 * 60 * 1000;
const cache = new Map<string, { at: number; body: unknown }>();

const isPrivate = (ip: string) =>
  ip === "::1" ||
  ip === "127.0.0.1" ||
  ip.startsWith("10.") ||
  ip.startsWith("192.168.") ||
  /^172\.(1[6-9]|2\d|3[01])\./.test(ip) ||
  ip.startsWith("fc") ||
  ip.startsWith("fd");

interface IpstackResponse {
  country_code?: string;
  country_name?: string;
  currency?: { code?: string };
  error?: { info?: string };
}

export async function GET(request: NextRequest) {
  // No key configured → let the client fall back to its default pair.
  if (!API_KEY) {
    return NextResponse.json({ currency: null, reason: "no-key" });
  }

  // Prefer the real client IP; fall back to ipstack's "check" (server IP) in
  // local dev where there's no forwarded client address.
  const xff = request.headers.get("x-forwarded-for");
  const candidate = xff?.split(",")[0]?.trim() ?? "";
  const target = candidate && !isPrivate(candidate) ? candidate : "check";

  // Serve a fresh cached result to avoid re-hitting ipstack on every load.
  const cached = cache.get(target);
  if (cached && Date.now() - cached.at < TTL_MS) {
    return NextResponse.json(cached.body);
  }

  const endpoint = `${IPSTACK_BASE}/${encodeURIComponent(target)}?access_key=${API_KEY}`;

  try {
    const res = await fetch(endpoint, { cache: "no-store" });
    const data = (await res.json()) as IpstackResponse;

    // Rate-limited or errored → serve last good result if we have one.
    if (data.error || !data.country_code) {
      if (cached) return NextResponse.json(cached.body);
      return NextResponse.json({
        currency: null,
        reason: data.error?.info ? "rate-limited" : "lookup-failed",
      });
    }

    // Use ipstack's own currency when present (paid plans), otherwise map from
    // the country code.
    const currency =
      (data.currency?.code && data.currency.code) ||
      countryToCurrency(data.country_code);

    const body = {
      currency,
      country: data.country_code,
      countryName: data.country_name ?? null,
    };
    cache.set(target, { at: Date.now(), body });
    return NextResponse.json(body);
  } catch {
    if (cached) return NextResponse.json(cached.body);
    return NextResponse.json({ currency: null, reason: "unreachable" });
  }
}

